skin:
#s95 .stage{background:linear-gradient(165deg,#191C1F,#0c0d10);color:#fff}
#s95 .d-nav{background:#27282F;border:1px solid #ffffff14;border-radius:16px}
#s95 .d-logo{font-weight:700;background:linear-gradient(90deg,#00B5F2,#5B3DF5);-webkit-background-clip:text;background-clip:text;color:transparent}
#s95 .d-links span{opacity:.6;color:#aaa}#s95 .d-links span:hover{opacity:1;color:#fff}
#s95 .d-h{font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
#s95 .d-p{color:#8b8d94}
#s95 .d-btn{background:linear-gradient(90deg,#00B5F2,#5B3DF5);color:#fff;border-radius:999px;font-weight:600;box-shadow:0 4px 18px #00b5f240}
#s95 .d-btn:hover{filter:brightness(1.15)}
#s95 .d-btn.ghost{background:#27282F;color:#cfd1d6;box-shadow:none}
#s95 .d-input{background:#27282F;border:1px solid #ffffff14;border-radius:999px;color:#fff}
#s95 .d-badge{background:linear-gradient(90deg,#00b5f222,#5b3df522);color:#9fd0ff;border:1px solid #ffffff1a;border-radius:999px}
#s95 .d-prog{background:#27282F}#s95 .d-prog i{background:linear-gradient(90deg,#00E09E,#00B5F2)}
#s95 .d-card{background:linear-gradient(140deg,#27282F,#1d1e24);border:1px solid #ffffff14;border-radius:16px;box-shadow:0 8px 28px #00b5f21f}
